import sqlite3

from flask import Flask, request

app = Flask(__name__)


@app.route("/compare")
def compare():
    ids = request.args.getlist("id")
    db = sqlite3.connect("catalog.db")
    if not ids:
        return {"items": []}
    placeholders = ",".join("?" for _ in ids)
    sql = "SELECT id, name, price FROM items WHERE id IN (" + placeholders + ")"
    return {"items": db.execute(sql, ids).fetchall()}

