from flask import Flask, request

app = Flask(__name__)


@app.post("/backup")
def backup():
    database = request.form["database"]
    if not re.fullmatch(r"[A-Za-z0-9_.-]+", database):
        return {"status": -1, "error": "invalid database name"}, 400
    with open("/var/backups/latest.sql", "wb") as out:
        status = subprocess.call(["pg_dump", database], stdout=out)
    return {"status": status}

