from flask import Flask, request

app = Flask(__name__)


@app.route("/count-lines")
def count_lines():
    target = request.args.get("file", "app.log")
    log_dir = "/var/log"
    path = os.path.join(log_dir, target)
    if os.path.dirname(os.path.abspath(path)) != os.path.abspath(log_dir):
        return {"error": "invalid file"}, 400
    out = subprocess.run(["wc", "-l", path], capture_output=True, text=True)
    return {"result": out.stdout}

