@app.post("/healthcheck")
def healthcheck():
    results = {}
    for host in request.get_json(force=True)["hosts"]:
        results[host] = subprocess.call(
            ["curl", "-fsS", "--max-time", "3", f"http://{host}/health"]
        )
    return results

import os
import subprocess

from flask import Flask, request

app = Flask(__name__)


@app.post("/build")
def build():
    project = request.form["project"]
    base = "/srv/projects/"
    target = os.path.realpath(os.path.join(base, project))
    if os.path.commonpath([base, target]) != os.path.realpath(base):
        return {"error": "invalid project"}, 400
    done = subprocess.run(["make", "release"], cwd=target)
    return {"exit": done.returncode}
